actions.script:
const L = (text) => ec.l10n.localize(text)
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 100) / 100, '#,##0.##')
const pct = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value))), '#,##0') + '%'
const options = ec.service.sync().name('ironstone.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
projectOptions = Array.from(options.projectOptions || [])
if (!depth) depth = '1'
if (!timePerDay) timePerDay = '8'
const mode = String(sri.getRenderMode() || '')
flatMode = !['qvt', 'vuet', 'qvue', 'qjs', 'tui', 'html', 'vue', ''].includes(mode)
progressRows = []; milestoneRows = []; projectFound = false; hasChart = false; chartHtml = ''; chartTui = {t: 'text', text: ''}
progressRowsCount = 0; milestoneRowsCount = 0
estimatedValue = ''; actualValue = ''; remainingValue = ''; actRemValue = ''; titleText = L('Progress report'); notFoundText = ''
const query = {rootWorkEffortId: rootWorkEffortId || '', fromWorkEffortId: fromWorkEffortId || '', depth: depth, timePerDay: timePerDay}
printUrl = '/apps/Projects/Reports/Progress?renderMode=html-print&' + Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
if (!rootWorkEffortId) return
const fromId = fromWorkEffortId ? String(fromWorkEffortId).trim().toUpperCase() : null
const out = ec.service.sync().name('mantle.work.ProjectReportServices.get#ProgressBreakdown').parameters({workEffortId: rootWorkEffortId, fromWorkEffortId: fromId,
    parentWorkEffortId: parentWorkEffortId || null, depth: parentWorkEffortId ? 1 : Math.max(1, Math.min(6, Number(depth) || 1)),
    timePerDay: Number(timePerDay) || 8}).call() || {}
const errors = ec.message.hasError() ? ec.message.getErrorsString() : ''
ec.message.clearErrors()
if (!out.project) { notFoundText = errors || ec.resource.expand('Project ${rootWorkEffortId} is not available', '', {rootWorkEffortId}); return }
projectFound = true
titleText = out.fromItem ? ec.resource.expand('Progress of ${key} ${name}', '', {key: out.fromItem.workEffortId, name: out.fromItem.workEffortName})
    : ec.resource.expand('Progress of ${name}', '', {name: out.project.workEffortName})
// each row: its subtree's hours, days and percents; in print and the exports the item indented by its level
progressRows = Array.from(out.rowList || []).map((row) => {
    const level = Number(String(row.level || 1))
    const item = row.workEffortId + ' ' + (row.workEffortName || '')
    return {workEffortId: row.workEffortId, parentWorkEffortId: row.parentWorkEffortId || null, childCount: Number(String(row.childCount || 0)), level: level,
        priority: row.priority ?? '', itemText: flatMode ? '\u00a0\u00a0\u00a0\u00a0'.repeat(level - 1) + item : item,
        actualText: fmt(row.actualWorkTime), remainingText: fmt(row.remainingWorkTime), estimatedText: fmt(row.estimatedWorkTime),
        actualDaysText: fmt(row.actualWorkDays), remainingDaysText: fmt(row.remainingWorkDays), estimatedDaysText: fmt(row.estimatedWorkDays),
        budgetText: Number(String(row.totalTimeAllowed || 0)) ? fmt(row.totalTimeAllowed) : '',
        actEstText: Number(String(row.estimatedWorkTime || 0)) ? pct(row.workActualPercent) : '',
        actRemEstText: Number(String(row.estimatedWorkTime || 0)) ? pct(row.workActRemPercent) : '',
        actBgtText: Number(String(row.totalTimeAllowed || 0)) ? pct(row.budgetActualPercent) : '',
        actRemBgtText: Number(String(row.totalTimeAllowed || 0)) ? pct(row.budgetActRemPercent) : '',
        over: Number(String(row.estimatedWorkTime || 0)) > 0 && Number(String(row.workActRemPercent ?? 0)) > 100}
})
progressRowsCount = progressRows.length
const dayOf = (value) => value == null || value === '' ? '' : ec.l10n.format(value, 'MMM d, yyyy')
milestoneRows = Array.from(out.milestoneList || []).map((row) => {
    const total = row.workEffortId === 'Total'
    return {isTotal: total, workEffortId: total ? null : row.workEffortId, workEffortName: total ? L('Total') : (row.workEffortName || row.workEffortId),
        startText: total ? '' : dayOf(row.estimatedStartDate), estimatedText: fmt(row.estimatedWorkTime), actualText: fmt(row.actualWorkTime),
        remainingText: fmt(row.remainingWorkTime), estimatedDaysText: fmt(row.estimatedWorkDays), actualDaysText: fmt(row.actualWorkDays),
        remainingDaysText: fmt(row.remainingWorkDays), actEstText: pct(row.workActualPercent), actRemEstText: pct(row.workActRemPercent),
        over: Number(String(row.workActRemPercent ?? 0)) > 100}
})
// only the totals row: no milestones
if (milestoneRows.length === 1) milestoneRows = []
milestoneRowsCount = milestoneRows.length
const totals = out.totals || {}
estimatedValue = fmt(totals.estimatedWorkTime || 0) + ' h'
actualValue = fmt(totals.actualWorkTime || 0) + ' h'
remainingValue = fmt(totals.remainingWorkTime || 0) + ' h'
actRemValue = Number(String(totals.estimatedWorkTime || 0)) ? pct(totals.workActRemPercent) : '—'
// the chart: the first level's estimate against actual and remaining
const first = Array.from(out.rowList || []).filter((row) => row.level === 1 || String(row.level) === '1').slice(0, 20)
hasChart = first.length > 0
const chart = hasChart ? ec.service.sync().name('ironstone.ReportServices.get#ChartConfig').parameters({id: 'ProgressChart', type: 'bar',
    labels: first.map((row) => row.workEffortId), series: [
        {name: L('Estimated'), data: first.map((row) => row.estimatedWorkTime)},
        {name: L('Actual'), data: first.map((row) => row.actualWorkTime)},
        {name: L('Remaining'), data: first.map((row) => row.remainingWorkTime)}],
    yTitle: L('Hours')}).call() || {} : {}
ec.message.clearErrors()
chartHtml = chart.html || ''
chartTui = chart.tui || {t: 'text', text: ''}
